  'settings.row.scriptShell.desc': '실행 스크립트, 셋업 및 보관 스크립트, 검사를 실행하는 셸: 명령 프롬프트, PowerShell 또는 Git Bash.',
  'settings.row.keepAgentsRunning.desc': 'Claude Code와 Codex 턴은 백그라운드 호스트에서 실행되므로 종료해도 계속 작업할 수 있습니다.',
