  'settings.row.archiveScript.desc': '워크스페이스를 보관하기 전에 순서대로 실행되는 이름 있는 단계로, 단계마다 제한 시간이 있습니다',
  'settings.row.repoDockerCleanup': '보관할 때 Docker 컨테이너 제거',
  'settings.row.repoDockerCleanup.desc': 'foreman.workspace 레이블에 워크스페이스 ID가 지정된 컨테이너를 제거합니다.',
  'settings.row.repoDockerExtras.desc': '익명 볼륨은 컨테이너와 함께 제거되고, 컨테이너가 사용하던 네트워크는 다른 곳에서 사용하지 않으면 제거됩니다.',
  'settings.row.repoChecks.desc': '검사 실행이 각 워크스페이스에서 실행하는 명령입니다.',
  'settings.row.repoChecksAfterTurn.desc': '턴이 완료되고 워크스페이스에서 다른 작업이 진행 중이지 않으면 검사를 실행합니다.',
  'settings.row.sensitivePaths.desc': '이 패턴과 일치하는 파일이 변경되면 자세히 확인하도록 표시합니다.',
  'settings.row.runMode.desc': '실행 스크립트를 시작할 때 저장소의 다른 워크스페이스에서 실행 중인 것을 중지할지 여부입니다.',
  'settings.row.teachAgents.desc': '막혔을 때, 입력이 필요할 때, 완료했을 때 보고하는 방법과 리뷰를 요청하는 방법을 에이전트에게 알려 줍니다.',
  'settings.row.agentsMayStart.desc': '에이전트 턴 안에서 foreman run과 foreman send를 허용합니다.',
  'settings.row.teachAgentsPreview.desc': '에이전트에게 Foreman 알려 주기로 각 에이전트가 받는 정확한 텍스트입니다.',
  'settings.row.planTheWork.desc': 'foreman run 스니펫으로 끝나는 리드 채팅 템플릿입니다.',
  'settings.row.spotlightTesting.desc': '워크스페이스 변경 사항을 저장소 루트에서 테스트합니다.',
  'settings.row.autoReview.desc': '작업자의 턴이 검사를 통과하면 읽기 전용 에이전트가 diff를 리뷰합니다. 기본적으로 꺼져 있습니다.',
  'settings.row.promptCodeReview.desc': '리뷰를 클릭할 때 에이전트에게 보내는 사용자 지정 지침입니다.',
  'settings.row.promptCreatePr.desc': 'PR 만들기를 클릭할 때 에이전트에게 보내는 사용자 지정 지침입니다.',
  'settings.row.promptFixErrors.desc': '오류 수정을 클릭할 때 에이전트에게 보내는 사용자 지정 지침입니다.',
  'settings.row.promptResolveConflicts.desc': '충돌 해결을 클릭할 때 에이전트에게 보내는 사용자 지정 지침입니다.',
  'settings.row.promptRenameBranch.desc': '메시지로 브랜치 이름을 생성할 때 사용하는 사용자 지정 지침입니다.',
  'settings.row.promptGeneral.desc': '새 채팅을 시작할 때마다 에이전트에게 보내는 사용자 지정 지침입니다.',
  'settings.row.previewUrls.desc': '터미널 패널의 URL 열기 대상을 설정합니다.',
  'settings.row.filesToCopy.desc': 'gitignore된 이 파일들을 새 워크스페이스마다 복사합니다.',

