  'tour.action.assistant': '어시스턴트 열기',
  'tour.action.accessibility': '설정 → 접근성 열기',
  'tour.step.welcome.title': 'Foreman에 오신 것을 환영합니다',
  'tour.step.welcome.body': '코딩 에이전트를 병렬로 실행하세요. 각 에이전트는 저장소의 별도 복사본, 별도 브랜치에서 작업합니다. 모든 것은 이 컴퓨터에 머뭅니다. 어디에 무엇이 있는지 알려 드릴게요.',
  'tour.step.addRepo.title': '저장소 추가',
  'tour.step.addRepo.body': '이미 git 저장소인 폴더를 열거나, GitHub에서 클론하거나, 빠른 시작으로 새로 만드세요. 저장소를 오른쪽 클릭하면 설정 스크립트, 실행 스크립트, 검사 같은 설정을 열 수 있습니다.',
  'tour.step.addRepo.where': '저장소 아이콘 줄의 + 버튼',
  'tour.step.newWorkspace.title': '워크스페이스 시작',
  'tour.step.newWorkspace.body': '각 워크스페이스는 자체 워크트리의 새 브랜치이며 포트와 터미널도 따로 있어 에이전트끼리 충돌하지 않습니다. {key}를 누르고 작업을 설명하세요. 이미지도 첨부할 수 있습니다.',
  'tour.step.newWorkspace.where': '위쪽의 새 워크스페이스 버튼',
  'tour.step.needsYou.title': '확인 필요',
  'tour.step.needsYou.body': '에이전트를 여러 개 실행하면 계속 지켜볼 수 없습니다. 승인, 질문, 계획, 실패한 턴 등 사용자를 기다리는 모든 것이 개수, 알림, 트레이 또는 메뉴 막대 배지와 함께 여기와 홈에 모입니다. {next}는 확인이 필요한 다음 워크스페이스로, {jump}는 현재 채팅에서 확인이 필요한 항목으로 이동합니다.',
  'tour.step.needsYou.where': '전체, 확인 필요, 실행 중, 고정 필터',
  'tour.step.layout.title': '작업을 보는 두 가지 방법',
  'tour.step.layout.body': '3패널은 워크스페이스 하나와 그 변경 내용, 터미널을 나란히 보여 주며 지금 쓰는 방식입니다. 타일은 여러 워크스페이스의 채팅을 나란히 보여 줍니다. {palette}(“타일로 전환”)나 설정 → 모양 → 창 레이아웃에서 언제든 바꿀 수 있습니다.',
  'tour.step.automations.title': '템플릿과 자동화',
  'tour.step.automations.body': '템플릿은 세부 내용을 채울 빈칸이 있는 프롬프트이며, 직접 만든 것이나 저장소의 것을 쓸 수 있습니다. 자동화는 Foreman이 열려 있는 동안 템플릿을 일정(매일, 매주 등)에 따라 실행하고, 실행된 것과 다음 일정을 달력으로 보여 줍니다.',
  'tour.step.automations.where': '사이드바 맨 위의 자동화',
  'tour.step.assistant.title': '어시스턴트에게 묻기',
  'tour.step.assistant.body': '무엇이 어디 있는지 모르겠다면 여기에서 물어보세요({key}). 정확한 설정 위치를 알려 주며 아무것도 바꾸지 않습니다. Claude로 동작하므로 먼저 Claude에 로그인하세요.',
  'tour.step.assistant.where': '자동화 아래의 어시스턴트',
  'tour.step.settings.title': '설정',
  'tour.step.settings.body': '접근성: 글자 크기, 확대, 색상 모드, 스크린 리더 안내. 에이전트: 로그인과 기본값 선택. MCP: 저장소 서버는 워크스페이스의 Git 패널에서 승인하며, 에이전트는 Foreman 자체 도구를 사용할 수 있습니다. 원격 워크스페이스(실험적, 기본적으로 꺼짐)는 클라우드 샌드박스에서 워크스페이스를 실행합니다.',
  'tour.step.settings.where': '저장소 아이콘 줄의 톱니바퀴',
  'tour.step.help.title': '언제든 여기서',
  'tour.step.help.body': '이 투어는 여기서 다시 볼 수 있습니다. 나머지는 모두 검색으로 찾을 수 있습니다: {palette}는 명령 팔레트를 열고 {shortcuts}는 모든 단축키를 보여 줍니다.',
  'tour.step.help.where': '저장소 아이콘 줄의 ?',

